const challengeDefinitions=[
 {id:'address',title:'01 / Find the missing user',scene:'users',goal:'Fetch user 1. This address points to a user that does not exist. Edit the URL and send a corrected request.',hint:'The existing user lives at demo://api/users/1. Keep the GET method.',prepare:()=>{$('#url').value='demo://api/users/999';},valid:(q,r)=>q.url==='demo://api/users/1'&&q.method==='GET'&&r.status===200&&r.data.id===1},
 {id:'auth',title:'02 / Get past the velvet rope',scene:'private',goal:'Open the protected profile. Add the missing Authorization header in the request editor, then send again.',hint:'Add "Authorization": "Bearer cinema-demo" to the Headers JSON object. Keep the existing Content-Type entry and use GET.',prepare:()=>{$('#headers').value=JSON.stringify({'Content-Type':'application/json'},null,2);},valid:(q,r)=>q.url==='demo://api/private'&&q.method==='GET'&&q.headers.get('Authorization')==='Bearer cinema-demo'&&r.status===200&&r.data.access==='granted'},
 {id:'json',title:'03 / Give your project a name',scene:'projects',goal:'Create a project. The body is missing a required name. Send valid JSON containing a non-empty name with POST.',hint:'Try {"name":"My first API project"} in the Body editor. Use POST and keep the /projects address.',prepare:()=>{$('#body').value='{"description":"A project without a name"}';},valid:(q,r)=>{let body;try{body=JSON.parse(q.body);}catch{return false;}return q.url==='demo://api/projects'&&q.method==='POST'&&typeof body.name==='string'&&!!body.name.trim()&&r.status===201&&r.data.created===true&&r.data.name===body.name;}}
];
let activeChallenge=null;let solved=[];try{const saved=JSON.parse(localStorage.getItem('cinema-challenges-v1')||'[]');if(Array.isArray(saved))solved=saved.filter(id=>challengeDefinitions.some(c=>c.id===id));}catch{}
function drawChallenges(){$('#progress').textContent=`${solved.length} / 3 SOLVED`;$('#challengeList').replaceChildren();challengeDefinitions.forEach(c=>{const b=document.createElement('button');b.type='button';b.className='challenge-card'+(activeChallenge===c?' selected':'');b.dataset.challenge=c.id;b.textContent=(solved.includes(c.id)?'✓ ':'')+c.title;b.onclick=()=>{if(busy)return;selectScene(c.scene);activeChallenge=c;c.prepare();$('.editor').open=true;$('#challengeTask').hidden=false;$('#challengeText').textContent=c.goal;$('#challengeFeedback').textContent='Send the broken request first, then make your fix.';drawChallenges();};$('#challengeList').append(b);});}
$('#hint').onclick=()=>{if(activeChallenge)$('#challengeFeedback').textContent=activeChallenge.hint;};
function leaveChallenge(){activeChallenge=null;$('#challengeTask').hidden=true;drawChallenges();}
$('#exitChallenge').onclick=leaveChallenge;
document.querySelectorAll('.scene').forEach(b=>b.addEventListener('click',leaveChallenge));
window.addEventListener('cinema:response',({detail:{request,response}})=>{if(!activeChallenge)return;const success=request&&activeChallenge.valid(request,response);if(success){if(!solved.includes(activeChallenge.id))solved.push(activeChallenge.id);try{localStorage.setItem('cinema-challenges-v1',JSON.stringify(solved));}catch{}$('#challengeFeedback').textContent='✓ Solved! Your corrected request returned the expected data. Try another challenge or compare your last two runs.';$('#challengeFeedback').className='solved';drawChallenges();}else{$('#challengeFeedback').textContent=`Not solved yet (${response.status||'network error'}). Check the goal, inspect the response, or open a hint.`;$('#challengeFeedback').className='';}});
drawChallenges();
